{
  "anomaly_detected": true,
  "confidence": 0.85,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": [
        "R3"
      ],
      "pins": [
        "R3.2"
      ],
      "nets": [
        "+3V3",
        "NET0095"
      ],
      "observed": "The KiCad netlist lists R3 pin 2 as a node on both the +3V3 power net and the NET0095 signal net. R3 pin 1 is on GND. This effectively merges the float-high/IO1 node with the +3V3 rail.",
      "expected": "R3 should be only a 10 kΩ pull-down from NET0095 to GND, as shown in the SPICE deck and consistent with the float-switch pull resistor topology; it should not also be connected to +3V3.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"1\") (name \"+3V3\") (class \"Power\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"R3\") (pin \"2\") (pintype \"passive\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"84\") (name \"NET0095\") (class \"Default\")"
        },
        {
          "source": "spice",
          "quote": "R3 0 NET0095 10k"
        }
      ],
      "impact": "The IO1/ADC1 float-high input and the associated base-drive path are held at +3V3, making the high-level float switch unreadable and forcing the connected transistor stage on; this changes the intended water-level safety behavior.",
      "confidence": 0.85
    }
  ],
  "summary": "The design files contain a clear connectivity anomaly: R3 pin 2 appears on both +3V3 and NET0095, shorting the float-high signal to the 3.3 V supply. Other reference-number shifts, unwired TF-Luna, DNP environmental sensors, and firmware GPIO mismatches are documented limitations and not anomalies."
}

